import { z } from 'zod';
import catalogJson from './catalog.json';

/**
 * The catalogue is generated by `pnpm --filter @peertoreel/render-worker ui:gallery`
 * from `ui-demo/gallery/catalog.ts`. It is validated at import time, so a stale
 * or hand-edited snapshot fails the build instead of rendering a broken card.
 */

const galleryValueSchema = z.union([z.string(), z.number(), z.boolean()]);

export const galleryParameterSchema = z.object({
  name: z.string().min(1),
  type: z.enum(['number', 'string', 'boolean', 'color', 'enum', 'asset']),
  min: z.number().optional(),
  max: z.number().optional(),
  values: z.array(z.union([z.string(), z.number()])).optional(),
  maxLength: z.number().int().positive().optional(),
  initial: galleryValueSchema,
});

export const galleryPrimitiveSchema = z.object({
  id: z.string().min(1),
  semantics: z.string().min(1),
  offeredToDirector: z.boolean(),
  parameters: z.array(galleryParameterSchema),
  states: z.array(z.string()),
  transitions: z.array(z.string()),
  operations: z.array(z.string()),
  prompt: z.array(z.string()),
});

export const galleryCatalogSchema = z.object({
  schemaVersion: z.literal(1),
  canvas: z.object({ width: z.number(), height: z.number() }),
  fps: z.number(),
  maxElementsPerScene: z.number(),
  maxInstancesPerPrimitive: z.number(),
  assets: z.array(z.string()),
  themes: z.array(
    z.object({
      id: z.string().min(1),
      background: z.string(),
      ink: z.string(),
      muted: z.string(),
      surface: z.string(),
      accent: z.string(),
      accentInk: z.string(),
    }),
  ),
  primitives: z.array(galleryPrimitiveSchema).min(1),
  preview: z.object({ channel: z.string().min(1), path: z.string().min(1) }),
});

export type GalleryValue = z.infer<typeof galleryValueSchema>;
export type GalleryParameter = z.infer<typeof galleryParameterSchema>;
export type GalleryPrimitive = z.infer<typeof galleryPrimitiveSchema>;
export type GalleryTheme = z.infer<typeof galleryCatalogSchema>['themes'][number];
export type GalleryCatalog = z.infer<typeof galleryCatalogSchema>;

export const GALLERY_CATALOG: GalleryCatalog = galleryCatalogSchema.parse(
  catalogJson,
);

/** The sandbox opens on the contract's own starting values. */
export function initialParams(
  primitive: GalleryPrimitive,
): Record<string, GalleryValue> {
  const params: Record<string, GalleryValue> = {};

  for (const parameter of primitive.parameters) {
    params[parameter.name] = parameter.initial;
  }

  return params;
}

export function primitiveById(id: string): GalleryPrimitive | null {
  return GALLERY_CATALOG.primitives.find((primitive) => primitive.id === id) ?? null;
}
